"""L1 biologie : notions de base de santé publique (prévention, épidémiologie, maladies courantes en Afrique centrale, nutrition,
santé maternelle et infantile, soins de santé primaires, premiers secours, éducation pour la santé).
Notions de cours seulement : ni statistiques, ni posologies, ni conseils médicaux individuels. Tout est `review`."""
from .sup_kit import *  # noqa: F401,F403

from .sup_kit import mcq as _mcq


def mcq(course, tpl, rows, **kw):
    """Les énoncés à compléter (finissant par « : ») deviennent des questions."""
    fixed = []
    for q, right, wrongs, expl, d in rows:
        if q.rstrip().endswith(":"):
            q = "Complétez la phrase « %s … » : quelle suite est exacte ?" % q.rstrip()[:-1].rstrip()
        fixed.append((q, right, wrongs, expl, d))
    _mcq(course, tpl, fixed, **kw)


