mcq(C, "san-mere", [
    ("À quoi servent les consultations prénatales (CPN) ?", "Suivre la grossesse, prévenir et dépister les complications et préparer l'accouchement", ["Faire accoucher les femmes à domicile", "Remplacer l'accouchement", "Choisir le sexe du bébé", "Vacciner l'enfant après la naissance"], "Les CPN protègent la mère et le fœtus.", 1),
    ("Que signifie « CPN » en santé maternelle ?", "Consultation prénatale", ["Contrôle post-natal", "Centre de protection néonatale", "Consultation du paludisme", "Comité de promotion nutritionnelle"], "Elle a lieu pendant la grossesse.", 1),
    ("Que signifie « CPoN » ?", "Consultation postnatale", ["Consultation préventive obligatoire", "Contrôle pédiatrique ordinaire", "Cabinet de promotion de la nutrition", "Contrat de prise en charge"], "Elle suit l'accouchement.", 2),
    ("Que désigne un accouchement assisté ?", "Un accouchement réalisé avec l'aide d'un personnel de santé qualifié", ["Un accouchement obligatoirement par césarienne", "Un accouchement sans personne", "Un accouchement à l'étranger", "Un accouchement sous anesthésie obligatoire"], "Il réduit les risques pour la mère et l'enfant.", 1),
    ("Pourquoi l'accouchement par du personnel qualifié réduit-il la mortalité maternelle ?", "Les complications (hémorragie, éclampsie…) sont détectées et prises en charge rapidement", ["Il supprime la grossesse", "Il évite d'avoir des enfants", "Il remplace les CPN", "Il rend la mère immunisée contre le paludisme"], "Les complications peuvent être mortelles sans soins rapides.", 3),
    ("Quel est un signe de danger pendant la grossesse nécessitant de consulter sans attendre ?", "Un saignement vaginal", ["Un léger appétit", "Une envie de sommeil", "Une humeur changeante légère", "Un mal de dos léger après une longue journée"], "Les saignements, les convulsions et les maux de tête intenses sont des signes d'alerte.", 2),
    ("Quelle complication de la grossesse est associée à une forte tension artérielle et à des convulsions possibles ?", "L'éclampsie", ["L'anémie falciforme", "Le rachitisme", "Le scorbut", "Le goitre"], "La pré-éclampsie peut évoluer en éclampsie.", 4),
    ("Laquelle de ces complications est une cause majeure de décès maternel ?", "L'hémorragie du post-partum", ["Le rhume", "La carie dentaire", "L'acné", "La myopie"], "Une perte de sang importante après l'accouchement est dangereuse.", 4),
    ("Que sont les « trois retards » à l'origine de décès maternels ?", "Retard à décider de consulter, retard à atteindre la structure, retard à recevoir des soins adéquats", ["Retard de croissance, retard de langage, retard scolaire", "Retard de paiement, retard de vaccination, retard de dépistage", "Retard d'ovulation, retard de naissance, retard d'allaitement", "Retard de décision politique, de vote et de promulgation"], "Modèle d'analyse des décès maternels.", 5),
    ("La planification familiale permet :", "de choisir le nombre et l'espacement des naissances", ["d'interdire toute naissance", "de remplacer les consultations prénatales", "de traiter le paludisme", "de dépister le cancer"], "Elle contribue à la santé de la mère et de l'enfant.", 1),
    ("Pourquoi espacer les naissances est-il bénéfique pour la santé ?", "Cela permet à la mère de récupérer et réduit les risques pour la mère et l'enfant", ["Cela supprime la fertilité", "Cela rend l'enfant plus lourd", "Cela évite le paludisme", "Cela remplace l'allaitement"], "Un intervalle suffisant entre deux grossesses protège.", 3),
    ("Que peut-on dire, en santé publique, d'une grossesse très précoce chez une adolescente ?", "Elle comporte des risques accrus pour la mère et l'enfant", ["Elle supprime les risques", "Elle remplace les CPN", "Elle protège contre le diabète", "Elle améliore toujours la santé"], "Le corps de l'adolescente n'est pas toujours prêt.", 3),
    ("Qu'est-ce que la mortalité néonatale ?", "Les décès de nouveau-nés pendant les premières semaines de vie", ["Les décès de femmes enceintes", "Les décès d'enfants de dix ans", "Les décès de personnes âgées", "Les décès de jeunes adultes"], "Elle couvre les 28 premiers jours.", 3),
    ("Quel est l'intérêt des soins du cordon ombilical propres chez le nouveau-né ?", "Prévenir les infections, dont le tétanos néonatal", ["Éviter les caries", "Réduire la fièvre jaune", "Éviter la rougeole", "Protéger de la bilharziose"], "Un cordon propre et sec limite les infections.", 3),
    ("Qu'est-ce que la méthode « mère kangourou » ?", "Le contact peau à peau entre la mère et le nouveau-né, surtout prématuré", ["Un régime alimentaire", "Un vaccin", "Une technique d'accouchement chirurgical", "Un test de dépistage"], "Elle maintient la chaleur et favorise l'allaitement.", 4),
    ("Que mesure la courbe de croissance dans le carnet de santé d'un enfant ?", "L'évolution du poids (et de la taille) en fonction de l'âge", ["Le nombre de vaccins", "Le nombre de frères et sœurs", "La température du corps", "Le niveau d'études"], "Elle permet de repérer tôt un trouble de la croissance.", 2),
    ("Pourquoi le suivi de la croissance est-il utile ?", "Il permet de repérer tôt la malnutrition et d'agir", ["Il remplace la vaccination", "Il permet de choisir une école", "Il guérit le paludisme", "Il remplace l'alimentation"], "Une cassure de la courbe est un signal d'alerte.", 2),
    ("Que signifie PCIME ?", "Prise en charge intégrée des maladies de l'enfant", ["Programme central d'immunisation maternelle", "Plan communautaire d'information médicale", "Protocole de contrôle infantile et mortalité", "Prévention du cancer infantile et maternelle"], "Approche qui traite ensemble les principales causes de maladie de l'enfant.", 4),
    ("Quelles sont parmi les principales causes de mortalité des enfants de moins de cinq ans en Afrique subsaharienne ?", "Le paludisme, les infections respiratoires aiguës et les maladies diarrhéiques", ["Le diabète et l'hypertension", "Le cancer et l'asthme allergique", "L'arthrose et la myopie", "La carie et l'acné"], "La PCIME cible ces causes.", 3),
    ("Quel signe général de danger chez un enfant malade impose un recours immédiat aux soins ?", "L'incapacité de boire ou de téter", ["Un appétit un peu augmenté", "Un jeu actif", "Une soif normale", "Un rire"], "Avec les convulsions et la léthargie, c'est un signe de gravité.", 3),
    ("Que faut-il prévenir ou traiter en priorité lors d'une diarrhée aiguë chez le nourrisson ?", "La déshydratation", ["Arrêter de lui donner à boire", "Lui donner des boissons très sucrées", "Éviter toute consultation", "Lui donner un antipaludique systématiquement"], "Réhydratation en priorité.", 3),
    ("Pourquoi vacciner les nourrissons dès le plus jeune âge ?", "Ils sont vulnérables à des infections graves avant d'avoir acquis leur propre immunité", ["Les vaccins ne sont efficaces que chez les nourrissons", "Ils ne risquent aucune maladie", "Les vaccins sont toujours des antibiotiques", "L'immunité maternelle est définitive"], "La protection doit précéder l'exposition.", 3),
    ("Qu'est-ce que la fistule obstétricale ?", "Une communication anormale entre organes, séquelle d'un accouchement prolongé sans soins", ["Une maladie due à un moustique", "Un trouble alimentaire", "Une maladie virale", "Une allergie"], "Un accès précoce à la césarienne la prévient.", 5),
    ("Quelle est la conséquence possible d'un accouchement très prolongé sans soins ?", "Des complications graves pour la mère et l'enfant", ["Un gain de poids régulier", "Une meilleure santé", "Une immunité contre la polio", "La fin de la grossesse"], "L'accès à un service obstétrical est vital.", 3),
    ("La césarienne est une intervention qui consiste à :", "extraire l'enfant par une incision de l'abdomen et de l'utérus", ["administrer un vaccin à la mère", "dépister un cancer", "traiter l'anémie", "déclencher un allaitement"], "Elle sauve des vies quand l'accouchement par voie basse est dangereux.", 3),
    ("Que sont les mutilations génitales féminines du point de vue de la santé publique ?", "Des pratiques néfastes pour la santé, sans bénéfice médical", ["Des soins de routine", "Des vaccins", "Des tests de dépistage", "Des traitements du paludisme"], "Elles exposent à des complications immédiates et à long terme.", 4),
    ("La drépanocytose est une maladie :", "génétique du globule rouge, fréquente en Afrique", ["virale transmise par moustique", "bactérienne de l'eau", "due à une carence en iode", "parasitaire transmise par une mouche"], "Elle est héréditaire et non contagieuse.", 3),
    ("Pour qu'un enfant soit atteint de drépanocytose (forme majeure), il faut en principe :", "qu'il ait reçu le gène anormal de chacun de ses deux parents", ["qu'il ait été piqué par un moustique", "que sa mère ait bu de l'eau souillée", "qu'il ait reçu un vaccin", "qu'il soit né en saison des pluies"], "Transmission autosomique récessive.", 5),
    ("Le conseil génétique et le dépistage avant le mariage ou la grossesse visent surtout :", "à informer les couples sur le risque de maladie héréditaire", ["à punir les porteurs d'un gène", "à guérir la maladie par vaccin", "à interdire le mariage", "à protéger du paludisme"], "Il s'agit d'une prévention fondée sur l'information.", 4),
], cat=CAT, src="sup-sante-mere-enfant")

# --------------------------------------------------------------------------------------------------------------------
# 6. Maladies non transmissibles
# --------------------------------------------------------------------------------------------------------------------
mcq(C, "san-mnt", [
    ("Qu'est-ce qu'une maladie non transmissible ?", "Une maladie qui ne se transmet pas d'une personne à une autre, souvent chronique", ["Une maladie qui se transmet par l'air", "Une maladie due à un moustique", "Une maladie qui disparaît seule en trois jours", "Une maladie due à une bactérie de l'eau"], "Diabète, hypertension, cancers et maladies respiratoires chroniques en sont des exemples.", 1),
    ("Lequel de ces groupes réunit des maladies non transmissibles ?", "Le diabète, l'hypertension artérielle et certains cancers", ["Le choléra, la rougeole et la polio", "Le paludisme, la dengue et la fièvre jaune", "La tuberculose, la syphilis et l'hépatite B", "La bilharziose, l'onchocercose et la dracunculose"], "Ce sont des maladies chroniques non contagieuses.", 2),
    ("Que mesure la glycémie ?", "Le taux de sucre (glucose) dans le sang", ["La tension du sang", "Le nombre de globules rouges", "La température", "La quantité d'eau dans l'organisme"], "Elle est élevée chez les diabétiques non équilibrés.", 2),
    ("Le diabète est une maladie caractérisée par :", "une glycémie trop élevée de façon chronique", ["une tension trop basse", "un manque de fer", "une infection virale du foie", "un excès d'iode"], "Il est lié à un défaut de production ou d'action de l'insuline.", 2),
    ("Quel est le rôle de l'insuline ?", "Faire baisser la glycémie en permettant l'utilisation du glucose par les cellules", ["Combattre les bactéries", "Fabriquer les globules rouges", "Transporter l'oxygène", "Coaguler le sang"], "L'insuline est une hormone produite par le pancréas.", 3),
    ("Quel organe produit l'insuline ?", "Le pancréas", ["Le foie", "Le rein", "Le cœur", "Le poumon"], "Ses cellules bêta sécrètent l'insuline.", 3),
    ("Quelle est la caractéristique principale du diabète de type 1 ?", "Un défaut de production d'insuline, le plus souvent chez le sujet jeune", ["Une carence en iode", "Une infection due à un moustique", "Un excès de sel", "Une anémie héréditaire"], "Il est le plus souvent d'origine auto-immune.", 4),
    ("Le diabète de type 2 est surtout associé :", "au surpoids, à la sédentarité et à une résistance à l'insuline", ["à une infection par un moustique", "à une carence en vitamine C", "à un manque d'eau", "à une exposition au soleil"], "C'est le diabète le plus fréquent.", 3),
    ("Parmi les complications possibles du diabète mal équilibré, on trouve :", "l'atteinte des yeux, des reins et des nerfs, et les plaies des pieds", ["le paludisme", "le tétanos", "le choléra", "la rougeole"], "L'excès chronique de sucre abîme les petits vaisseaux.", 3),
    ("Pourquoi les soins des pieds sont-ils importants chez le diabétique ?", "Les plaies guérissent mal et peuvent s'infecter gravement", ["Les pieds ne sont jamais touchés", "Cela remplace le traitement", "Cela supprime la glycémie", "Cela évite le paludisme"], "Prévention des complications.", 3),
    ("Qu'est-ce que l'hypoglycémie ?", "Une baisse excessive du taux de sucre dans le sang", ["Une hausse excessive du sucre dans le sang", "Une baisse de la tension", "Un manque de globules rouges", "Une infection"], "Elle peut provoquer malaise et perte de connaissance.", 3),
    ("Qu'est-ce que l'hypertension artérielle ?", "Une pression du sang sur les parois des artères trop élevée de façon durable", ["Un taux de sucre trop élevé", "Un manque de globules rouges", "Une infection des artères", "Une pression trop basse"], "Elle est souvent silencieuse.", 2),
    ("Pourquoi appelle-t-on parfois l'hypertension un « tueur silencieux » ?", "Elle peut évoluer longtemps sans symptôme tout en abîmant les organes", ["Elle provoque toujours des douleurs vives", "Elle se transmet en silence", "Elle ne touche que les muets", "Elle disparaît toute seule"], "Le dépistage régulier est donc important.", 3),
    ("Quelles complications sont liées à une hypertension non traitée ?", "Accident vasculaire cérébral, insuffisance cardiaque et atteinte des reins", ["Rougeole, polio et tétanos", "Paludisme, dengue et fièvre jaune", "Scorbut, rachitisme et goitre", "Teigne, gale et poux"], "Elle fatigue les vaisseaux et les organes.", 3),
    ("Qu'est-ce qu'un accident vasculaire cérébral (AVC) ?", "L'atteinte du cerveau par l'obstruction ou la rupture d'un vaisseau", ["Une infection des poumons", "Une fracture", "Une intoxication alimentaire", "Une anémie"], "Il peut entraîner paralysie et troubles de la parole.", 3),
    ("Quel appareil sert à mesurer la tension artérielle ?", "Un tensiomètre", ["Un thermomètre", "Un stéthoscope uniquement", "Un glucomètre", "Un otoscope"], "Il mesure la pression systolique et diastolique.", 1),
    ("Quel appareil sert à mesurer la glycémie capillaire ?", "Un glucomètre", ["Un tensiomètre", "Un thermomètre", "Un spiromètre", "Un otoscope"], "On utilise une goutte de sang prélevée au doigt.", 1),
    ("Lequel de ces comportements est un facteur de risque de maladie chronique ?", "La sédentarité", ["Une activité physique régulière", "Une alimentation variée", "Le sommeil suffisant", "Le lavage des mains"], "L'inactivité favorise obésité, diabète et maladies cardiovasculaires.", 2),
    ("Les quatre grands facteurs de risque comportementaux des maladies chroniques sont :", "le tabac, l'alcool, une alimentation déséquilibrée et la sédentarité", ["la vaccination, le dépistage, la prévention et l'éducation", "l'eau, l'air, la terre et le feu", "le froid, le chaud, l'humidité et le vent", "le sommeil, le repos, le jeu et la lecture"], "Ils sont communs à plusieurs maladies chroniques.", 4),
    ("Pourquoi le tabagisme est-il un problème de santé publique ?", "Il augmente le risque de cancers, de maladies cardiovasculaires et respiratoires", ["Il protège du cancer", "Il remplace la vaccination", "Il traite l'hypertension", "Il améliore la santé des poumons"], "Il touche aussi les non-fumeurs exposés (tabagisme passif).", 2),
    ("Le tabagisme passif désigne :", "l'exposition à la fumée de tabac des autres", ["la consommation de tabac mâché uniquement", "l'arrêt volontaire du tabac", "la fumée d'une cuisine uniquement", "un type de vaccin"], "Les non-fumeurs exposés subissent aussi des risques.", 3),
    ("Qu'est-ce que l'obésité ?", "Un excès de masse grasse pouvant nuire à la santé", ["Un manque d'appétit chronique", "Un excès de muscle seulement", "Une infection", "Une carence en protéines"], "Elle favorise diabète, hypertension et problèmes articulaires.", 2),
    ("L'asthme est une maladie :", "chronique des voies respiratoires, avec des crises de gêne respiratoire", ["infectieuse transmise par l'eau", "virale due à un moustique", "génétique du sang", "due à une carence en fer"], "Il n'est pas contagieux.", 3),
    ("Pourquoi les maladies non transmissibles sont-elles un enjeu croissant en Afrique ?", "L'urbanisation, le mode de vie et le vieillissement les rendent plus fréquentes", ["Parce que les maladies infectieuses ont totalement disparu", "Parce qu'elles sont toutes contagieuses", "Parce qu'elles ne touchent que les enfants", "Parce qu'elles ne sont plus soignées"], "Elles s'ajoutent aux maladies transmissibles.", 4),
    ("Un dépistage du diabète vise à :", "repérer une glycémie anormale avant l'apparition de complications", ["guérir le diabète", "vacciner contre le diabète", "traiter le paludisme", "remplacer l'alimentation"], "Le diagnostic précoce permet une prise en charge plus tôt.", 2),
    ("L'éducation thérapeutique du patient chronique a pour but de :", "l'aider à comprendre sa maladie et à gérer son traitement au quotidien", ["remplacer le médecin", "supprimer le traitement", "cacher le diagnostic", "faire payer plus cher"], "Elle améliore l'observance et limite les complications.", 4),
    ("L'activité physique régulière est un facteur de :", "protection contre plusieurs maladies chroniques", ["risque de paludisme", "risque d'hypertension", "risque de tétanos", "risque de choléra"], "Elle améliore le cœur, le poids et la glycémie.", 2),
    ("La consommation excessive d'alcool est un facteur de risque de :", "cirrhose du foie et de certains cancers", ["rachitisme", "goitre", "scorbut", "gale"], "L'alcool abîme le foie.", 3),
    ("Qu'est-ce qu'un cancer ?", "Une multiplication anormale et incontrôlée de cellules", ["Une infection due à un moustique", "Une carence en vitamine", "Une allergie", "Une maladie due aux vers"], "Certains cancers sont favorisés par des infections (HPV, hépatite B).", 3),
    ("Quel cancer peut être prévenu en grande partie par la vaccination contre le papillomavirus humain ?", "Le cancer du col de l'utérus", ["Le cancer de la prostate", "Le cancer de la peau", "Le cancer du poumon", "Le cancer du côlon"], "Le HPV est la cause principale de ce cancer.", 4),
    ("Quel cancer la vaccination contre l'hépatite B contribue-t-elle à prévenir ?", "Le cancer du foie", ["Le cancer du sein", "Le cancer de l'estomac", "Le cancer du poumon", "Le cancer de la peau"], "L'infection chronique par le virus de l'hépatite B augmente le risque.", 5),
], cat=CAT, src="sup-sante-secours")

# --------------------------------------------------------------------------------------------------------------------
# 7. Premiers secours et éducation pour la santé
# --------------------------------------------------------------------------------------------------------------------
mcq(C, "san-secours", [
    ("Que signifie la séquence « Protéger, Alerter, Secourir » ?", "Sécuriser les lieux, appeler les secours, puis porter assistance", ["Soigner, guérir, vacciner", "Donner un médicament, filmer, partir", "Déplacer, laver, cacher", "Attendre, regarder, noter"], "C'est l'ordre logique de l'intervention d'un secouriste.", 1),
    ("Devant un accident, quelle est la première action d'un secouriste ?", "Se protéger et protéger les lieux pour éviter un sur-accident", ["Déplacer immédiatement tous les blessés", "Donner à boire à la victime", "Quitter les lieux", "Prendre des photos"], "Sans sécurité, le secouriste peut devenir une victime.", 2),
    ("Quel service doit-on alerter dans un accident grave ?", "Les secours (service d'urgence)", ["Un ami quelconque seulement", "Un garagiste", "Un commerçant", "Une école"], "Il faut donner le lieu, la nature de l'accident et le nombre de victimes.", 1),
    ("Que doit-on préciser quand on alerte les secours ?", "Le lieu exact, la nature de l'accident et le nombre de victimes", ["Le nom de ses parents", "Son âge uniquement", "Son prix de vente", "Son métier uniquement"], "Ces informations permettent d'envoyer des moyens adaptés.", 2),
    ("Une victime inconsciente qui respire doit être placée :", "en position latérale de sécurité (PLS)", ["sur le dos, la tête relevée haut", "assise", "debout", "sur le ventre jambes pliées sans appui"], "La PLS libère les voies aériennes et évite l'étouffement par les vomissements.", 3),
    ("Pourquoi place-t-on une victime inconsciente qui respire en PLS ?", "Pour dégager les voies aériennes et éviter l'étouffement", ["Pour la réveiller", "Pour la réchauffer", "Pour lui donner à boire", "Pour la faire dormir"], "La langue ou les vomissements pourraient obstruer les voies aériennes.", 3),
    ("Face à une victime inconsciente qui ne respire pas, que doit-on faire en urgence ?", "Alerter les secours et pratiquer un massage cardiaque", ["Lui donner à boire", "L'asseoir", "Attendre qu'elle se réveille", "La laisser seule"], "Sans circulation, les organes souffrent en quelques minutes.", 3),
    ("Que doit-on faire face à un saignement abondant d'une plaie ?", "Comprimer la plaie directement avec un tissu propre", ["La laisser à l'air libre sans rien faire", "Mettre de la terre sur la plaie", "Ôter tous les tissus", "Laisser saigner"], "La compression directe est le geste de base.", 2),
    ("Comment nettoie-t-on une petite plaie ?", "Avec de l'eau propre et du savon, puis on protège par un pansement propre", ["Avec de la terre", "Avec du sable", "Avec de la salive", "On ne la nettoie jamais"], "Éviter l'infection.", 2),
    ("Que faut-il faire en cas de brûlure légère ?", "Refroidir la zone avec de l'eau fraîche courante", ["Appliquer du beurre", "Percer les cloques", "Appliquer de la glace directement très longtemps", "Mettre de l'huile chaude"], "Le refroidissement limite l'étendue de la brûlure.", 3),
    ("Pourquoi ne faut-il pas appliquer de corps gras sur une brûlure ?", "Cela retient la chaleur et peut favoriser l'infection", ["Cela refroidit trop", "Cela guérit sans cicatrice", "Cela protège de l'infection", "Cela calme toute douleur"], "Le geste de base est le refroidissement à l'eau.", 4),
    ("Que fait-on lors d'une morsure de serpent ?", "On immobilise la victime et on la conduit en urgence vers un centre de soins", ["On incise la morsure", "On aspire le venin avec la bouche", "On pose un garrot serré", "On fait courir la victime"], "Éviter les gestes dangereux et gagner du temps.", 4),
    ("Lors d'une morsure de serpent, quel geste est à proscrire ?", "Inciser la plaie ou sucer le venin", ["Garder la victime calme et immobile", "Retirer bagues et bracelets", "Appeler les secours", "Noter l'heure de la morsure"], "Ces gestes sont inefficaces et dangereux.", 4),
    ("Que faire devant un adulte qui s'étouffe et ne peut plus parler ni respirer ?", "Pratiquer des claques dans le dos ou la manœuvre de Heimlich et alerter les secours", ["Lui donner à boire", "Le laisser s'allonger", "Lui donner du pain", "Le faire courir"], "Il faut libérer les voies aériennes rapidement.", 4),
    ("Que faire devant une personne en crise convulsive ?", "La protéger des chocs et la laisser sur le côté après la crise, sans rien lui mettre dans la bouche", ["Lui mettre un objet entre les dents", "La maintenir fortement", "Lui donner à boire pendant la crise", "L'asseoir sans soutien"], "Il ne faut ni la retenir ni rien lui mettre dans la bouche.", 4),
    ("Peut-on donner à boire à une personne inconsciente ?", "Non, elle risque de s'étouffer", ["Oui, toujours de l'eau", "Oui, du lait", "Oui, du thé chaud", "Oui, en grande quantité"], "Les réflexes de déglutition sont absents.", 3),
    ("Que faut-il faire en cas de suspicion de fracture d'un membre ?", "Immobiliser le membre et ne pas le mobiliser inutilement", ["Le masser fortement", "Le tirer pour le remettre en place", "Faire marcher la victime", "Appliquer de la chaleur"], "L'immobilisation limite la douleur et les lésions.", 3),
    ("Que fait-on en cas d'intoxication par ingestion d'un produit ménager ?", "On contacte un service d'urgence ou un centre antipoison sans faire vomir sauf avis médical", ["On fait vomir systématiquement", "On donne à manger", "On attend deux jours", "On donne un alcool"], "Certains produits sont plus dangereux lors des vomissements.", 4),
    ("Le contenu minimal d'une trousse de premiers secours comprend :", "des compresses, des pansements, un antiseptique et des gants", ["des aliments", "des vêtements neufs", "des outils de jardinage", "des jouets"], "Elle permet de traiter les petites plaies et d'attendre les secours.", 2),
    ("Pourquoi un secouriste doit-il se laver les mains et, si possible, porter des gants ?", "Pour se protéger et protéger la victime des infections", ["Pour mieux voir", "Pour effacer les empreintes", "Pour réchauffer la victime", "Pour économiser du temps"], "Les précautions d'hygiène limitent la transmission.", 3),
    ("Qu'est-ce que le choc en secourisme ?", "Une défaillance grave de la circulation, par exemple après une grosse hémorragie", ["Un simple stress passager", "Une simple colère", "Un coup de soleil léger", "Un vertige léger"], "Il faut alerter immédiatement les secours.", 5),
    ("En cas de coup de chaleur, que faut-il faire ?", "Mettre la personne à l'ombre, la rafraîchir et alerter les secours", ["La couvrir de plusieurs couvertures", "La faire courir", "Lui donner de l'alcool", "L'exposer au soleil"], "L'hyperthermie peut être grave.", 4),
    ("En présence d'un saignement de nez simple, on :", "fait pencher la tête en avant et on comprime les narines", ["fait pencher la tête en arrière", "met un objet dans le nez", "donne de l'alcool", "fait courir la personne"], "La tête en arrière fait avaler le sang.", 4),
    ("Un geste de premier secours doit-il remplacer l'avis d'un médecin dans une situation grave ?", "Non, il permet de gagner du temps en attendant les secours", ["Oui, toujours", "Oui, dans tous les cas", "Oui, pour un accident de la route", "Oui, si la victime refuse"], "Les premiers secours ne se substituent pas aux soins médicaux.", 2),
], cat=CAT, src="sup-sante-secours")

mcq(C, "san-edu", [
    ("Que vise la communication pour le changement de comportement en santé ?", "Favoriser l'adoption de comportements bénéfiques pour la santé", ["Imposer des sanctions", "Vendre des médicaments", "Remplacer les vaccins", "Fermer des centres de santé"], "Elle s'appuie sur l'information, la persuasion et l'appui social.", 3),
    ("Qu'est-ce qu'une causerie éducative ?", "Une discussion avec un petit groupe sur un thème de santé", ["Un examen médical", "Un traitement", "Un vaccin", "Un test sanguin"], "Elle favorise les échanges avec la communauté.", 2),
    ("Un « pair-éducateur » est :", "une personne du même groupe (âge, milieu) formée pour sensibiliser ses pairs", ["Un médecin spécialiste", "Un inspecteur", "Un agent d'assurance", "Un pharmacien"], "La proximité facilite l'écoute des messages.", 3),
    ("Pourquoi adapter les messages de santé à la culture locale ?", "Ils sont mieux compris et acceptés par la population", ["Cela supprime tout message", "Cela interdit l'éducation", "Cela remplace le dépistage", "Cela évite les vaccins"], "L'éducation doit tenir compte des croyances et des pratiques.", 3),
    ("Lequel de ces supports est utilisé en éducation pour la santé ?", "Affiches, causeries, démonstrations et émissions radio", ["Ordonnances uniquement", "Seringues", "Stéthoscopes", "Radiographies"], "Divers canaux atteignent différents publics.", 2),
    ("Pourquoi la radio est-elle un support efficace de sensibilisation en zone rurale ?", "Elle touche un large public, y compris des personnes qui ne lisent pas", ["Elle remplace le médecin", "Elle supprime les maladies", "Elle soigne à distance", "Elle est réservée aux enfants"], "Elle atteint des auditeurs éloignés.", 3),
    ("Une démonstration pratique du lavage des mains est efficace parce qu'elle :", "montre le geste à reproduire", ["remplace le savon", "dure toute la journée", "supprime l'eau", "est interdite aux enfants"], "Voir et faire aide à apprendre.", 2),
    ("Quelle est la différence entre information et éducation pour la santé ?", "L'éducation vise un changement de comportement, l'information transmet des connaissances", ["Il n'y en a aucune", "L'information soigne, l'éducation vaccine", "L'éducation est réservée aux adultes", "L'information n'existe pas en santé"], "Savoir ne suffit pas toujours à changer de pratique.", 4),
    ("Qu'est-ce que la promotion de la santé selon la Charte d'Ottawa ?", "Un processus qui donne aux populations plus de maîtrise de leur santé", ["Un programme de vente de médicaments", "Une obligation de vaccination", "Une surveillance policière", "Une campagne de dépistage uniquement"], "Elle dépasse la seule responsabilité des services de soins.", 4),
    ("Dans la promotion de la santé, que signifie « créer des environnements favorables » ?", "Aménager le cadre de vie pour qu'il soutienne la santé (eau, air, logement, espaces sûrs)", ["Construire uniquement des hôpitaux", "Interdire les marchés", "Supprimer les routes", "Imposer le silence"], "Les environnements influencent les comportements.", 4),
    ("Un « plaidoyer » en santé consiste à :", "défendre une cause de santé auprès de décideurs pour obtenir des mesures", ["vendre un produit", "soigner un malade", "rédiger une ordonnance", "faire une analyse"], "Il vise des politiques favorables à la santé.", 4),
    ("Dans une communauté, la mobilisation sociale pour la santé signifie :", "associer les habitants, les associations et les chefs à l'action de santé", ["interdire aux habitants de se réunir", "remplacer le personnel de santé", "supprimer toute information", "envoyer uniquement des médicaments"], "L'adhésion de la communauté conditionne le succès des programmes.", 3),
    ("Quel est l'intérêt de la participation de la communauté aux soins de santé primaires ?", "Elle favorise l'appropriation des actions et leur durabilité", ["Elle supprime toute action de l'État", "Elle remplace les médicaments", "Elle empêche les vaccinations", "Elle rend les soins plus chers"], "La communauté devient actrice de sa santé.", 3),
    ("Une évaluation d'un programme de santé cherche à savoir :", "dans quelle mesure les objectifs ont été atteints", ["combien coûte un hôpital uniquement", "qui a le plus de pouvoir", "quel malade est le plus malade", "quel médicament est vendu"], "Elle mesure l'effet des actions menées.", 3),
    ("Parmi ces cibles d'une campagne de sensibilisation, laquelle est la plus pertinente pour prévenir le tétanos néonatal ?", "Les femmes enceintes", ["Les personnes âgées", "Les commerçants", "Les chauffeurs", "Les enseignants du secondaire"], "Vaccination et accouchement propre protègent le nouveau-né.", 3),
    ("Pourquoi les campagnes de sensibilisation sur le VIH doivent-elles aussi combattre la stigmatisation ?", "La peur du rejet décourage le dépistage et le traitement", ["Parce que le virus se transmet par les mots", "Parce que la stigmatisation protège", "Parce qu'elle supprime le virus", "Parce qu'elle remplace les ARV"], "Le soutien social améliore la prise en charge.", 3),
], cat=CAT, src="sup-sante-secours")
